package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a name is required, the grade
 *  is one of A, B or C, the grade's from-date (optional) a real yyyy-mm-dd date, the terms (optional)
 *  blank or a whole number of days. Publishes the request with its name trimmed and its contact (optional)
 *  trimmed and lower-cased. */
public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (name.length() > 200) {
            throw new InvalidPersonException("A name is at most 200 characters.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date, yyyy-mm-dd.");
            }
        }
        String terms = request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.isEmpty() && !terms.matches("\\d{1,4}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank for none.");
        }
        String contact = request.contact() == null ? null : request.contact().trim().toLowerCase(Locale.ROOT);
        if (contact != null && contact.length() > 200) {
            throw new InvalidPersonException("A contact is at most 200 characters.");
        }
        body.set(new PersonRequest(request.user().trim(), name, grade, request.version(),
                gradeFrom.isEmpty() ? null : gradeFrom,
                terms == null || terms.isEmpty() ? terms : String.valueOf(Integer.parseInt(terms)), contact));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse adding a person whose name, or contact, another person on the sheet already has, or whose name is a name
 *  or alias on another sheet of the sheet's tree. */
public class ValidateNewPersonName {
    public void validate(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            PersonRepository repository) throws DuplicatePersonNameException, DuplicatePersonContactException {
        if (repository.nameInUse(sheetId.trim(), request.name(), null)) {
            throw new DuplicatePersonNameException(request.name());
        }
        DuplicatePersonNameException.refuseInTree(sheetId.trim(), request.name(), repository);
        if (request.contact() != null && !request.contact().isEmpty()
                && repository.contactInUse(sheetId.trim(), request.contact(), null)) {
            throw new DuplicatePersonContactException(request.contact());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuse renaming a person to a name, or giving them a contact, another person on the sheet already has; and refuse
 *  any edit leaving their name, or one of their aliases, a name or alias on another sheet of the sheet's tree. */
public class ValidatePersonName {
    public void validate(@Val PersonRequest request, @Val Person loaded, PersonRepository repository)
            throws DuplicatePersonNameException, DuplicatePersonContactException {
        if (repository.nameInUse(loaded.sheetId(), request.name(), loaded.id())) {
            throw new DuplicatePersonNameException(request.name());
        }
        // A person who already clashes may be edited only by a rename to a name, and with aliases, that do not.
        DuplicatePersonNameException.refuseInTree(loaded.sheetId(), request.name(), repository);
        for (String alias : loaded.aliases()) {
            DuplicatePersonNameException.refuseInTree(loaded.sheetId(), alias, repository);
        }
        if (request.contact() != null && !request.contact().isEmpty()
                && repository.contactInUse(loaded.sheetId(), request.contact(), loaded.id())) {
            throw new DuplicatePersonContactException(request.contact());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveNewPerson {
    public void save(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            PersonRepository repository, Out<Person> person) {
        person.set(repository.insert(sheetId.trim(), request.name(), request.grade(),
                request.terms() == null || request.terms().isEmpty() ? null : Integer.valueOf(request.terms()),
                request.contact() == null || request.contact().isEmpty() ? null : request.contact()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file. */
public class AuditPersonAdded {
    public void audit(@Val PersonRequest request, @Val Person person, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + person.sheetId() + " by=" + request.user()
                + " name=" + person.name() + " grade=" + person.grade()
                + (request.terms() != null && !request.terms().isEmpty() ? " terms=" + request.terms() : "")
                + (request.contact() != null && !request.contact().isEmpty() ? " contact=" + request.contact() : ""));
    }
}
package net.officefloor.hq.app.person;

/** Body of a person add or edit: who is making it, and the person's name and grade. An edit also
 *  names the version of the person it was made from (null: not checked), and the date its grade applies
 *  from (yyyy-mm-dd; null: the sheet's today). An add's grade applies from the beginning of time. The person's own terms are a whole
 *  number of days, "" for none (on an edit: clears them), or null when not given (on an edit: left as they are).
 *  The contact likewise: "" for none (on an edit: clears it), or null when not given. */
public record PersonRequest(String user, String name, String grade, Long version, String gradeFrom, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class RespondWithPersonCreated {
    public void respond(@Val Person person, ObjectResponse<ResponseEntity<PersonResponse>> response) {
        response.send(new ResponseEntity<>(PersonResponse.from(person), HttpStatus.CREATED));
    }
}

