# Paste claims: each line name,amount,date,note (the note may end " #<reference>") adds a DRAFT claim for the named person, in order. Every line is
# checked first by the claim form's rules (and the name must be on the sheet, and no reference used on the sheet or earlier in the paste); one failing line refuses the whole
# paste, which writes nothing, not even an audit line. Responds with how many were added.
validate:
  class: net.officefloor.hq.app.claim.ValidatePaste
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: paste
paste:
  class: net.officefloor.hq.app.claim.PasteClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithPaste
  govern: [ transaction ]
# Give the selected people a grade together from a from-date (blank: the sheet's today), in list order. Each is
# graded exactly as the person form's edit would (name and terms kept), with its PERSON_EDITED line and then how the
# sheet's figures moved over it. A refused request (no user, no people, a bad grade or date) writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateBulkGrade
  next: grade
grade:
  class: net.officefloor.hq.app.person.BulkGradePeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithBulkGrade
  govern: [ transaction ]
package net.officefloor.hq.app.person;

/** A person add or edit to a name another person on the sheet, or on another sheet of its tree, already has. */
public class DuplicatePersonNameException extends Exception {
    public DuplicatePersonNameException(String name) {
        super("The name " + name + " is already in use on this sheet.");
    }

    /** The name is already a name or alias on another sheet of this sheet's tree. */
    public DuplicatePersonNameException(String name, String sheetId) {
        super("The name " + name + " is already in use on sheet " + sheetId + ", in this sheet's tree.");
    }

    /** Refuse the name when another sheet of the sheet's tree already has it as a name or an alias. */
    public static void refuseInTree(String sheetId, String name, PersonRepository repository)
            throws DuplicatePersonNameException {
        String other = repository.sheetInTreeUsing(sheetId, name);
        if (other != null) {
            throw new DuplicatePersonNameException(name, other);
        }
    }
}
