package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written. Each non-blank line is name,grade,terms,contact
 *  — the terms and contact may be absent or blank — and must pass exactly the person form's rules; no two lines may
 *  give the same name, or the same contact (compared as the sheet compares them). A paste with no lines is refused.
 *  A refusal names the first line that fails. */
public class ValidateImport {
    public void validate(@RequestBody ImportRequest request, Out<ImportInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String user = request.user().trim();
        String[] rows = (request.text() == null ? "" : request.text()).split("\\r?\\n|\\r", -1);
        List<ImportLine> lines = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (int i = 0; i < rows.length; i++) {
            if (rows[i].isBlank()) {
                continue;
            }
            int number = i + 1;
            String[] fields = rows[i].split(",", 4);
            try {
                PersonRequest person = ValidatePerson.check(new PersonRequest(user, fields[0],
                        fields.length > 1 ? fields[1] : "", null, null, fields.length > 2 ? fields[2] : "",
                        fields.length > 3 ? fields[3] : ""));
                if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
                    throw new DuplicatePersonNameException(person.name());
                }
                if (!person.contact().isEmpty() && !contacts.add(person.contact())) {
                    throw new DuplicatePersonContactException(person.contact());
                }
                lines.add(new ImportLine(number, person));
            } catch (InvalidPersonException | DuplicatePersonNameException | DuplicatePersonContactException e) {
                throw new InvalidPersonException("Line " + number + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) {
            throw new InvalidPersonException("Paste at least one line: name,grade,terms,contact.");
        }
        body.set(new ImportInput(user, lines));
    }
}
EOF
cat > ImportPeople.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Check every imported person against the sheet first, as the person form would: their name not a name or alias
 *  on the sheet or another sheet of its tree, their contact not another person's. Any failure refuses the whole
 *  import, naming the line, and nothing is written. Otherwise each is added in order just as the form adds them:
 *  their PERSON_ADDED line and then how the sheet's figures moved over it. */
public class ImportPeople {
    public void importPeople(@PathVariable("sheetId") String sheetId, @Val ImportInput input,
            PersonRepository repository, Rollups rollups, Audit audit, Out<ImportResponse> result)
            throws InvalidPersonException {
        String sheet = sheetId.trim();
        for (ImportLine line : input.lines()) {
            PersonRequest request = line.person();
            try {
                if (repository.nameInUse(sheet, request.name(), null)) {
                    throw new DuplicatePersonNameException(request.name());
                }
                DuplicatePersonNameException.refuseInTree(sheet, request.name(), repository);
                if (!request.contact().isEmpty() && repository.contactInUse(sheet, request.contact(), null)) {
                    throw new DuplicatePersonContactException(request.contact());
                }
            } catch (DuplicatePersonNameException | DuplicatePersonContactException e) {
                throw new InvalidPersonException("Line " + line.number() + ": " + e.getMessage());
            }
        }
        for (ImportLine line : input.lines()) {
            PersonRequest request = line.person();
            Rollup before = rollups.take(sheet);
            Person person = repository.insert(sheet, request.name(), request.grade(),
                    request.terms().isEmpty() ? null : Integer.valueOf(request.terms()),
                    request.contact().isEmpty() ? null : request.contact());
            AuditPersonAdded.record(request, person, audit);
            rollups.record(sheet, input.user(), before);
        }
        result.set(new ImportResponse(input.lines().size()));
    }
}
EOF
